#include <memory>

#include "rclcpp/rclcpp.hpp"
#include "battery_msgs/srv/set_limit.hpp"

using SetLimit = battery_msgs::srv::SetLimit;

class GuardNode : public rclcpp::Node
{
public:
  GuardNode()
  : Node("guard")
  {
    service_ = create_service<SetLimit>(
      "set_limit",
      std::bind(&GuardNode::handle_set_limit, this, std::placeholders::_1, std::placeholders::_2));
    RCLCPP_INFO(get_logger(), "guard node ready, serving /set_limit");
  }

private:
  void handle_set_limit(
    const std::shared_ptr<SetLimit::Request> request,
    std::shared_ptr<SetLimit::Response> response)
  {
    RCLCPP_INFO(get_logger(), "set_limit request: max_voltage=%.3f", request->max_voltage);
    response->accepted = request->max_voltage > 0.0f;
  }

  rclcpp::Service<SetLimit>::SharedPtr service_;
};

int main(int argc, char ** argv)
{
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<GuardNode>());
  rclcpp::shutdown();
  return 0;
}

